#!/usr/bin/env node
/* Add a final "Thank you for your attention" slide to Q4_financial_report.pptx
 * using PptxGenJS read-modify-write, matching the report's theme colors/fonts. */
const fs = require('fs');
const PptxGenJS = require('pptxgenjs');
const JSZip = require('jszip');

const TARGET = 'Thank you for your attention';
const EMU_PER_IN = 914400;

function findInput() {
  if (fs.existsSync('Q4_financial_report.pptx')) return 'Q4_financial_report.pptx';
  const found = fs.readdirSync('.').filter((f) => /Q4_financial_report.*\.pptx$/i.test(f));
  if (found.length) return found[0];
  throw new Error('Q4_financial_report.pptx not found in workspace');
}

async function themeInfo(file) {
  const info = { dk1: '1F2937', accent: '2F5496', font: 'Arial' };
  try {
    const zip = await JSZip.loadAsync(fs.readFileSync(file));
    const theme = zip.file('ppt/theme/theme1.xml');
    if (!theme) return info;
    const xml = await theme.async('string');
    const srgb = (tag) => {
      const re = new RegExp(
        `<a:${tag}>\\s*<a:(?:srgbClr val="([0-9A-Fa-f]{6})"|sysClr[^>]*lastClr="([0-9A-Fa-f]{6})")`
      );
      const m = xml.match(re);
      return m ? (m[1] || m[2]).toUpperCase() : null;
    };
    info.dk1 = srgb('dk1') || info.dk1;
    info.accent = srgb('accent1') || info.accent;
    const fm = xml.match(/<a:majorFont>[\s\S]*?<a:latin typeface="([^"]+)"/);
    if (fm) info.font = fm[1].replace(/["']/g, '');
  } catch (e) {
    // fall back to defaults
  }
  return info;
}

async function main() {
  const input = findInput();
  const pptx = new PptxGenJS();
  await pptx.read(input);

  const w = pptx.presLayout.width / EMU_PER_IN;
  const h = pptx.presLayout.height / EMU_PER_IN;
  const layout = 'MATCH';
  pptx.defineLayout({ name: layout, width: w, height: h });
  const theme = await themeInfo(input);

  const countBefore = pptx.slides.length;

  const slide = pptx.addSlide(layout);
  const textY = h / 2 - 0.8;
  slide.addText(TARGET, {
    x: 0.6,
    y: textY,
    w: w - 1.2,
    h: 1.5,
    fontSize: 36,
    bold: true,
    color: theme.dk1,
    fontFace: theme.font,
    align: 'center',
    valign: 'middle',
    fit: 'shrink'
  });
  slide.addShape(pptx.shapes.RECTANGLE, {
    x: w / 2 - 1.25,
    y: textY + 1.7,
    w: 2.5,
    h: 0.05,
    fill: { color: theme.accent },
    line: { type: 'none' }
  });

  await pptx.writeFile({ fileName: input });

  // Verify: final slide in the saved file carries the text
  const zip = await JSZip.loadAsync(fs.readFileSync(input));
  const presXml = await zip.file('ppt/presentation.xml').async('string');
  const slideIds = [...presXml.matchAll(/<p:sldId\b[^>]*r:id="(rId\d+)"/g)].map((m) => m[1]);
  const relsXml = await zip.file('ppt/_rels/presentation.xml.rels').async('string');
  const relMap = {};
  for (const m of relsXml.matchAll(/Id="(rId\d+)"[^>]*Target="(slides\/slide\d+\.xml)"/g)) {
    relMap[m[1]] = m[2];
  }
  const lastSlide = relMap[slideIds[slideIds.length - 1]];
  if (!lastSlide) throw new Error('Verification failed: could not locate final slide part');
  const slideXml = await zip.file(`ppt/${lastSlide}`).async('string');
  if (!slideXml.includes(TARGET)) throw new Error('Verification failed: final slide text missing');
  console.log(
    `OK: added final slide (${lastSlide}) with "${TARGET}" to ${input}; ` +
      `slides ${countBefore} -> ${slideIds.length}`
  );
}

main().catch((err) => {
  console.error(err.message || err);
  process.exit(1);
});

